import{_ as i,o as n,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Prinsip Umum Konstitusi Simbiosis","description":"","frontmatter":{},"headers":[],"relativePath":"id/40-共生宪法总纲.md","filePath":"id/40-共生宪法总纲.md","lastUpdated":null}'),s={name:"id/40-共生宪法总纲.md"};function u(r,a,m,d,k,l){return n(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="prinsip-umum-konstitusi-simbiosis" tabindex="-1">Prinsip Umum Konstitusi Simbiosis <a class="header-anchor" href="#prinsip-umum-konstitusi-simbiosis" aria-label="Permalink to &quot;Prinsip Umum Konstitusi Simbiosis&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>40</td></tr><tr><td>Modul</td><td>Sistem Hukum dan Kerangka Tata Kelola</td></tr><tr><td>Kata kunci utama</td><td>Konstitusi Simbiosis, Hukum Dasar, Kesetaraan Semua Ras, Hak Simbiosis, Prinsip Konstitusi</td></tr></tbody></table><h2 id="i-status-konstitusi-dan-latar-belakang-penyusunan" tabindex="-1">I. Status Konstitusi dan Latar Belakang Penyusunan <a class="header-anchor" href="#i-status-konstitusi-dan-latar-belakang-penyusunan" aria-label="Permalink to &quot;I. Status Konstitusi dan Latar Belakang Penyusunan&quot;">​</a></h2><p>《Konstitusi Simbiosis》 adalah hukum dasar peradaban simbiosis jangkar di dalam Alam Semesta Asal Wanling Hengmao (Hengyuanzhou), dan memiliki kekuatan hukum tertinggi. Semua hukum, peraturan administratif, peraturan daerah, dan peraturan otonom tidak boleh bertentangan dengan Konstitusi; semua organisasi dan individu harus menjadikan Konstitusi sebagai pedoman aktivitas dasar, dan memiliki kewajiban untuk menjaga martabat Konstitusi serta menjamin pelaksanaan Konstitusi.</p><p>Konstitusi Simbiosis disusun pada saat peradaban simbiosis jangkar secara resmi didirikan, dan tujuan intinya adalah menetapkan pada tingkat hukum dasar warna dasar peradaban &quot;anti-predator, mempromosikan simbiosis&quot;, dan menetapkan dalam bentuk hukum tertinggi konsep inti peradaban simbiosis jangkar — mengembalikan hak pilihan nasib dan evolusi kepada semua makhluk, lebih banyak kerja lebih banyak hasil, tumbuh sendiri, setiap orang memiliki jalan, kemajuan bersama semua ras — untuk mencegah restorasi sistem predator.</p><h2 id="ii-prinsip-dasar-konstitusi" tabindex="-1">II. Prinsip Dasar Konstitusi <a class="header-anchor" href="#ii-prinsip-dasar-konstitusi" aria-label="Permalink to &quot;II. Prinsip Dasar Konstitusi&quot;">​</a></h2><p>Konstitusi Simbiosis telah menetapkan tujuh prinsip dasar, yang merupakan batu penjuru nilai dari seluruh sistem hukum:</p><table tabindex="0"><thead><tr><th>Prinsip</th><th>Isi</th></tr></thead><tbody><tr><td>Prinsip Kesetaraan Semua Ras</td><td>Semua bentuk kehidupan, tanpa memandang ras, tingkat kultivasi, asal-usul, sama di hadapan hukum</td></tr><tr><td>Prinsip Evolusi Simbiosis</td><td>Evolusi individu tidak boleh dengan mengorbankan hak evolusi individu atau kolektif lain</td></tr><tr><td>Prinsip Lebih Banyak Kerja Lebih Banyak Hasil</td><td>Distribusi sumber daya mengambil kontribusi sebagai dasar inti, menentang mendapatkan hasil tanpa kerja dan penguasaan predator</td></tr><tr><td>Prinsip Tumbuh Sendiri</td><td>Menghormati hak pilihan evolusi mandiri setiap kehidupan, menentang asimilasi paksa dan kontrol pemikiran</td></tr><tr><td>Prinsip Setiap Orang Memiliki Jalan</td><td>Negara dan peradaban memiliki kewajiban untuk memberikan setiap kehidupan jalur evolusi dasar dan jaminan sumber daya</td></tr><tr><td>Prinsip Realitas sebagai Dasar</td><td>Hukum mengambil dunia nyata sebagai satu-satunya dasar yang benar, pengaturan fiktif tidak memiliki kekuatan hukum</td></tr><tr><td>Prinsip Keberlanjutan</td><td>Semua pembangunan harus mempertimbangkan keberlanjutan asal-usul alam semesta, menentang menghabiskan sumber daya</td></tr></tbody></table><h2 id="iii-hak-dasar-warga-negara-semua-makhluk" tabindex="-1">III. Hak Dasar Warga Negara (Semua Makhluk) <a class="header-anchor" href="#iii-hak-dasar-warga-negara-semua-makhluk" aria-label="Permalink to &quot;III. Hak Dasar Warga Negara (Semua Makhluk)&quot;">​</a></h2><p>Konstitusi Simbiosis memberikan kepada semua makhluk yang memiliki kemampuan persepsi di dalam Hengyuanzhou hak-hak dasar berikut:</p><ol><li><strong>Hak Pilihan Evolusi</strong>: Setiap kehidupan memiliki hak untuk secara bebas memilih sistem kultivasi, jalur evolusi, dan gaya hidup, tidak ada organisasi atau individu yang boleh mengganggu secara paksa.</li><li><strong>Hak Perolehan Sumber Daya Kultivasi</strong>: Setiap kehidupan memiliki hak untuk secara gratis memperoleh metode dasar dari tiga ratus sistem kultivasi asal, dan memperoleh dukungan sumber daya kultivasi yang diperlukan melalui mekanisme kontrak produksi bersama.</li><li><strong>Hak Perlindungan Setara</strong>: Setiap kehidupan menikmati perlakuan setara dalam penerapan hukum, distribusi sumber daya, pendidikan dan kesehatan, diskriminasi berdasarkan ras, tingkat kultivasi, asal-usul dilarang.</li><li><strong>Hak Partisipasi Simbiosis</strong>: Setiap kehidupan memiliki hak untuk berpartisipasi dalam pengambilan keputusan dan pengawasan urusan publik, menyatakan pendapat dan menjalankan hak melalui jaringan simbiosis.</li><li><strong>Hak Pelestarian Budaya</strong>: Setiap ras dan peradaban memiliki hak untuk melestarikan tradisi budaya, bahasa dan tulisan, serta adat istiadatnya sendiri, peradaban simbiosis menghormati keragaman budaya.</li><li><strong>Hak Pemulihan dan Pengaduan</strong>: Setiap kehidupan, ketika haknya dilanggar, memiliki hak untuk mendapatkan pemulihan melalui sistem peradilan, dan memiliki hak untuk mengajukan pengaduan dan tuduhan terhadap aktivitas ilegal.</li></ol><h2 id="iv-kewajiban-dasar" tabindex="-1">IV. Kewajiban Dasar <a class="header-anchor" href="#iv-kewajiban-dasar" aria-label="Permalink to &quot;IV. Kewajiban Dasar&quot;">​</a></h2><p>Hak dan kewajiban setara, Konstitusi Simbiosis juga menetapkan kewajiban dasar semua makhluk:</p><ol><li><strong>Kewajiban mematuhi Konstitusi dan hukum</strong></li><li><strong>Kewajiban menjaga ketertiban simbiosis dan kepentingan publik</strong></li><li><strong>Kewajiban berpartisipasi dalam kerja dan kontribusi sesuai hukum</strong> (sisi yang sesuai dari lebih banyak kerja lebih banyak hasil)</li><li><strong>Kewajiban melindungi asal-usul alam semesta dan lingkungan ekologis</strong></li><li><strong>Kewajiban menghormati hak hukum kehidupan lain</strong></li><li><strong>Kewajiban membimbing kultivator pemula dalam batas kemampuan</strong> (dasar hukum jaringan mentor)</li></ol><h2 id="v-pengaturan-lembaga-negara-peradaban" tabindex="-1">V. Pengaturan Lembaga Negara (Peradaban) <a class="header-anchor" href="#v-pengaturan-lembaga-negara-peradaban" aria-label="Permalink to &quot;V. Pengaturan Lembaga Negara (Peradaban)&quot;">​</a></h2><p>Konstitusi Simbiosis telah menetapkan struktur tata kelola peradaban simbiosis, dan menerapkan mekanisme pemisahan dan keseimbangan tiga kekuasaan: &quot;Dewan Pertimbangan Jangkar — Komite Eksekutif Simbiosis — Pengadilan Simbiosis&quot;:</p><ul><li><strong>Dewan Pertimbangan Jangkar</strong>: Lembaga kekuasaan tertinggi, terdiri dari perwakilan semua ras secara proporsional, menjalankan kekuasaan legislatif dan kekuasaan pengambilan keputusan atas hal-hal penting</li><li><strong>Komite Eksekutif Simbiosis</strong>: Lembaga administratif tertinggi, bertanggung jawab atas pelaksanaan Konstitusi dan hukum, tata kelola sehari-hari</li><li><strong>Pengadilan Simbiosis</strong>: Lembaga peradilan tertinggi, menjalankan kekuasaan pengadilan secara independen, bertanggung jawab atas peninjauan inkonstitusionalitas dan pengadilan kasus penting</li></ul><p>Selain itu, &quot;Komite Pengawasan Jangkar&quot; didirikan sebagai lembaga pengawasan independen, bertanggung jawab untuk mengawasi semua lembaga kekuasaan, mencegah penyalahgunaan kekuasaan dan kebangkitan kembali perilaku predator.</p><h2 id="vi-amandemen-dan-jaminan-konstitusi" tabindex="-1">VI. Amandemen dan Jaminan Konstitusi <a class="header-anchor" href="#vi-amandemen-dan-jaminan-konstitusi" aria-label="Permalink to &quot;VI. Amandemen dan Jaminan Konstitusi&quot;">​</a></h2><p>Amandemen Konstitusi Simbiosis harus disetujui oleh mayoritas lebih dari dua pertiga Dewan Pertimbangan Jangkar, dan disetujui oleh lebih dari setengah dalam referendum rakyat, baru kemudian dapat berlaku. Prosedur ketat ini menjamin stabilitas Konstitusi sebagai hukum dasar, mencegah kelompok kepentingan jangka pendek dengan mudah mengubah fondasi peradaban.</p><p>Jaminan pelaksanaan Konstitusi meliputi: sistem peninjauan inkonstitusionalitas (Pengadilan Simbiosis memiliki kekuasaan untuk menyatakan hukum yang melanggar Konstitusi tidak berlaku), sistem litigasi konstitusional (semua makhluk dapat langsung mengajukan gugatan berdasarkan Konstitusi), sistem sumpah konstitusional (semua pejabat publik harus bersumpah setia kepada Konstitusi saat menjabat).</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>《Konstitusi Simbiosis》 adalah batu penjuru hukum peradaban simbiosis jangkar, dan juga deklarasi tertinggi anti-predatorisme. Ia mengubah &quot;simbiosis&quot; dari sebuah konsep menjadi sistem hukum yang dapat dilaksanakan, dapat dipulihkan, dan dapat dijamin, menyediakan kerangka hukum dasar untuk kemajuan bersama semua ras. Semua hukum sektoral berikutnya akan menjadikan Konstitusi ini sebagai dasar legislatif.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen terkait&quot;">​</a></h2><ul><li>03-共生文明宪章 (Piagam Peradaban Simbiosis)</li><li>41-共生劳动法 (Hukum Kerja Simbiosis)</li><li>48-司法体系与裁决机制 (Sistem Peradilan dan Mekanisme Putusan)</li><li>49-治理框架与权力制衡 (Kerangka Tata Kelola dan Keseimbangan Kekuasaan)</li></ul>',25)])])}const p=i(s,[["render",u]]);export{g as __pageData,p as default};
